common_contract.types:
type UUID = string;
type Seq = string;                 // decimal non-negative bigint, no Number conversion
type Revision = string;            // opaque equality token, never arithmetic in the UI
type Ref = { kind: string; id: string; version?: string };
type VerifiedContext = {
  actor: { kind: 'person' | 'agent' | 'system'; id: string };
  estate_id: string;
  scope: { kind: 'estate' } | { kind: 'project'; project_id: string };
  authority_revision: Revision;
  binding_revision?: Revision;
  epoch?: Seq;
};
type Command<T> = {
  command_id: string;              // caller persists across retries
  expected_revision?: Revision;
  input: T;                       // context is injected by trusted boundary, not input
};
type CommandResult<T> =
  | { status: 'committed'; value: T; receipt_ref: Ref }
  | { status: 'refused'; code: string; retryable: false; detail?: string }
  | { status: 'conflict'; current_revision: Revision; current_ref?: Ref }
  | { status: 'unavailable'; retryable: true; request_id: string }
  | { status: 'unknown'; request_id: string; reconcile_after_ms: number };

type ReadEnvelope<T> = {
  data: T | null;
  availability: 'complete' | 'partial' | 'unavailable';
  freshness: 'fresh' | 'stale' | 'unknown';
  as_of: string | null;            // ISO timestamp for observed snapshot
  at_seq: Seq | null;             // high-water actually covered by this query
  revision: Revision | null;
  sources: Array<{
    name: string;
    status: 'ok' | 'error' | 'not_configured' | 'not_supported';
    as_of: string | null;
    error_code?: string;
  }>;
  omitted: { count: number | null; reason: string }[];
  next_cursor: string | null;
};

// Internal trusted augmentation; never caller supplied. Public authority shape stays VerifiedContext.
type RuntimeVerifiedContext = Readonly<VerifiedContext & {
  task_run_id?: UUID; fabric_session_id?: UUID; role_slot_id?: UUID;
  leadership_role?: 'ceo' | 'product-manager'; role_epoch?: Seq;
  lease_epoch?: Seq; host_generation?: UUID; binding_id?: UUID;
  allowed_ops: readonly string[];
}>;
type Observation<T> = {source:'fabric'|'provider'|'agent_claim'|'operator';observed_at:string;received_at:string;evidence_ref?:Ref;value:T};
type CorrelationV2 = {workflow_run_id?:UUID;task_run_id?:UUID;fabric_session_id?:UUID;node_occurrence_id?:UUID;loop_iteration_ref?:{loop_key:string;iteration:number};attempt_id?:UUID;command_id:UUID;causation_id?:UUID};
